import urllib.request
import trafilatura
import json
import sys

def scrape_url(url):
    print(f"Scraping {url}...")
    req = urllib.request.Request(
        url,
        headers={'User-Agent': 'Mozilla/5.0 (compatible; OpenClawScout/1.0)'}
    )
    try:
        with urllib.request.urlopen(req, timeout=12) as response:
            html = response.read().decode('utf-8')
            text = trafilatura.extract(html, output_format='markdown')
            return text
    except Exception as e:
        print(f"Error scraping {url}: {e}", file=sys.stderr)
        return None

urls = [
    "https://www.coindesk.com/business/2026/06/02/moneygram-launches-stablecoin-on-stellar-joining-rush-toward-digital-dollar-payments",
    "https://beincrypto.com/moneygram-mgusd-stablecoin-stellar/"
]

scraped = {}
for url in urls:
    txt = scrape_url(url)
    if txt:
        scraped[url] = txt
        print(f"  Successfully extracted {len(txt)} chars")
    else:
        print(f"  Failed extraction for {url}")

print(f"Total scraped articles: {len(scraped)}")
with open("/home/bhard/.openclaw/workspace-researcher/mg_scraped.json", "w") as f:
    json.dump(scraped, f, indent=2)

