function findA(html) {
  // Let's find all '<a' tags that have 'target=\"_blank\"' or have a 'href' with some characteristics.
  const regex = /<a[^>]*href=\"([^\"]+)\"[^>]*>/g;
  let m;
  const set = new Set();
  while ((m = regex.exec(html)) !== null) {
    if (!m[1].includes('google') && !m[1].includes('gstatic')) {
      set.add(m[1]);
    }
  }
  return Array.from(set);
}

